(function(){var STORAGE_KEY='chalet_cookie_consent';var EXPIRY_DAYS=180;function getConsent(){try{var data=JSON.parse(localStorage.getItem(STORAGE_KEY));if(!data||!data.timestamp)return null;var age=Date.now()-data.timestamp;if(age>EXPIRY_DAYS*24*60*60*1000){localStorage.removeItem(STORAGE_KEY);return null;}
return data;}catch(e){return null;}}
function setConsent(categories){localStorage.setItem(STORAGE_KEY,JSON.stringify({categories:categories,timestamp:Date.now()}));if(categories.analytics){loadGTM();}
hideBanner();}
function loadGTM(){var gtmMeta=document.querySelector('meta[name="gtm-id"]');var gtmId=gtmMeta?gtmMeta.getAttribute('content'):'';if(!gtmId||window._gtmLoaded)return;window._gtmLoaded=true;window.dataLayer=window.dataLayer||[];window.dataLayer.push({'gtm.start':new Date().getTime(),event:'gtm.js'});var s=document.createElement('script');s.async=true;s.src='https://www.googletagmanager.com/gtm.js?id='+gtmId;document.head.appendChild(s);}
function showBanner(){var banner=document.getElementById('cookieConsent');if(banner)banner.style.display='';}
function hideBanner(){var banner=document.getElementById('cookieConsent');if(banner)banner.style.display='none';}
function init(){var consent=getConsent();if(consent&&consent.categories){if(consent.categories.analytics)loadGTM();return;}
showBanner();var acceptBtn=document.getElementById('cookieAccept');var rejectBtn=document.getElementById('cookieReject');var configBtn=document.getElementById('cookieConfigure');var saveBtn=document.getElementById('cookieSave');var mainScreen=document.getElementById('cookieMain');var configScreen=document.getElementById('cookieConfig');if(acceptBtn)acceptBtn.addEventListener('click',function(){setConsent({analytics:true});});if(rejectBtn)rejectBtn.addEventListener('click',function(){setConsent({analytics:false});});if(configBtn)configBtn.addEventListener('click',function(){mainScreen.style.display='none';configScreen.style.display='';});if(saveBtn)saveBtn.addEventListener('click',function(){var analyticsToggle=document.getElementById('cookieAnalytics');setConsent({analytics:analyticsToggle?analyticsToggle.checked:false});});}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();